  Archive --> Agents["LLM + Recruiter Discovery"]`,images:[],thumbnail:"",hideImages:!0,createdAt:"2026-05-14"},{id:75,title:"Research Claim Ledger",aliases:["research claim audit","claim ledger skill","academic source receipt"],description:"ClawHub skill-build case study for turning research drafts, source packets, literature matrices, or reviewer notes into source-backed claim ledgers.",longDescription:"Research Claim Ledger is a narrow public ClawHub skill for academic and technical writing review. It avoids the over-broad promise of a full research suite and focuses on one trust-building artifact: a claim-by-claim ledger that marks each sentence as supported, weakly-supported, overclaimed, wrong-source, missing-locator, stale-source, inaccessible, unsupported, or needing human review. The public case study compares this narrower wedge against broad academic-agent workflows and frames the deliverable as a receipt a writer can share with a supervisor, coauthor, or reviewer.",projectKind:"case-study",surfaceTags:["research","ai","release-engineering","openclaw"],keyFeatures:["Turns draft sections, literature matrices, notes, citation lists, source packets, or reviewer comments into a structured claim ledger","Separates supported claims from overclaims, missing locators, stale sources, inaccessible evidence, and human-review cases","Keeps the first release instruction-only with no bundled scraping helper or hidden dependency surface","Positions the skill as a small evidence receipt rather than a paper-writing, plagiarism, legal, medical, or financial review tool"],techStack:["ClawHub","Codex Skills","Research QA","Citation Review","Markdown","Release Engineering"],benchmarks:[{label:"ClawHub downloads",value:"186",context:"public ClawHub listing, 2026-06-03"},{label:"Published versions",value:"1",context:"public ClawHub listing, 2026-06-03"},{label:"Verdict labels",value:"9",context:"supported, weakly-supported, overclaimed, wrong-source, missing-locator, stale-source, inaccessible, unsupported, needs-human-review"},{label:"Release posture",value:"instruction-only",context:"SKILL.md and agent config first release; scripts deferred until example ledgers prove the workflow"}],links:[{text:"Open on ClawHub",url:"https://clawhub.ai/zack-dev-cm/research-claim-ledger"},{text:"Reference academic-research-skills",url:"https://github.com/Imbad0202/academic-research-skills"},{text:"Reference academic-research-skills-codex",url:"https://github.com/Imbad0202/academic-research-skills-codex"}],images:[],thumbnail:"",hideImages:!0,createdAt:"2026-05-22",canonicalLinks:{website:"https://clawhub.ai/zack-dev-cm/research-claim-ledger"}},{id:50,title:"HH OpenClaw Agent",description:"Public OpenClaw skill for reviewed hh.ru application packets, live browser execution, approval gates, and auditable submission bundles.",longDescription:"HH OpenClaw Agent is a small public OpenClaw skill for hh.ru application work through OpenClaw. It creates a machine-readable packet for one vacancy response flow, logs the live browser steps with evidence, validates the resulting bundle, and renders a markdown report for review, debugging, or funnel tracking. The public workflow requires an approved review state before submit and treats login, CAPTCHA, passkey, and 2FA as operator-owned interruptions.",keyFeatures:["Creates one machine-readable application packet with vacancy details, cover letter content, review state, and blocked actions","Appends evidence-backed browser steps with status, effect, artifacts, issue keys, and optional outcome URL","Checks approval state, failed-step detail, screenshot coverage, and unsafe absolute artifact paths before the bundle is shared","Renders a concise markdown report for job-funnel review, debugging, and operator handoff"],techStack:["ClawHub","Python","hh.ru","OpenClaw Skills","Career Automation"],benchmarks:[{label:"ClawHub downloads",value:"450",context:"public ClawHub listing, 2026-06-03"},{label:"Published versions",val